-- Manufacturer image URLs taken from the J5436 product bulletin.
-- Keep uploaded images preferred; attach only to matching colour codes.
UPDATE products SET colours = (SELECT json_group_array(json(CASE WHEN json_extract(value, '$.code') = '14312' AND json_extract(value, '$.image_id') IS NULL THEN json_set(value, '$.source_image_url', 'https://canada.beaulieucanada.com/images/5436-1/Thumb_Hires-5436-14312.jpg?_w=600') ELSE value END)) FROM json_each(products.colours)) WHERE id = '14c12ec4-a886-4501-8df9-ed3e2be9d964';
